import { useDisplay } from "vuetify/lib/framework.mjs";
import EditVistorrep from "@/components/VisitsManagementApp/AdminApp/AdminDialogues/EditVistorrep.vue";
import DeleteVistrep from "@/components/VisitsManagementApp/AdminApp/AdminDialogues/DeleteVistrep.vue";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import SnackBar from "@/components/SnackBar.vue";
import { list_all_visit_reps } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    SnackBar,
    DeleteVistrep,
    EditVistorrep
  },
  mixins: [get_all_org_users],
  data() {
    return {
      headers: [{
        title: "User",
        value: "user_email_id"
      }, {
        title: "Visit Types",
        value: "visit_type_names"
      }, {
        title: "Actions",
        value: "actions"
      }],
      tableData: [],
      allUSersNames: [],
      tableLoading: false,
      fixed: true,
      componentCheck: 0,
      itemsPerPage: 10,
      currentPage: 1,
      page: 1,
      vistrepdeletion: false,
      vistrepedition: false,
      visitTypeDialog: false,
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      rowInfo: {}
    };
  },
  computed: {
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async mounted() {
    this.CommonVuetifyObj = useDisplay();
    await this.get_all_org_users();
    await this.fetch_userrep();
    this.allUSersNames = this.orgUsers;
  },
  methods: {
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.vistrepdeletion = false;
      this.vistrepedition = false;
      this.tableData = [];
      this.fetch_userrep();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    edit_visitorrep(item) {
      this.componentCheck = 1;
      this.rowInfo = item;
      this.vistrepedition = true;
    },
    delete_visitorrep(item) {
      this.componentCheck = 2;
      this.rowInfo = item;
      this.vistrepdeletion = true;
    },
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      if (value == "SYSTEM") {
        name = value;
      }
      return name;
    },
    async fetch_userrep() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_all_visit_reps, {}));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_all_visit_reps);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.tableData = response.data;
          this.totalItems = this.tableData.length;
        } else {
          this.tableLoading = false;
          this.tableData = [];
          this.totalItems = [];
        }
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
